def initialize(context):
    log.set_level('system', 'error')
    set_option("avoid_future_data", True)
    set_benchmark('399006.XSHE')
    set_option('use_real_price', True)
    set_order_cost(OrderCost(open_tax=0, close_tax=0.001,
                             open_commission=0.00025, close_commission=0.00025,
                             min_commission=5), type='stock')
    set_slippage(FixedSlippage(0.001))

    # ---------- 参数 ----------
    g.position_ratio = 0.5        # 半仓轮动
    # 卖出模式: 'close'=次日14:55尾盘市价(41.5倍) | 'limit8'=次日09:33挂今开+8%限价/14:55兜底(26.9倍)
    #           'holdzt'=涨停持有断板卖(44.5倍) | 'chand'=吊灯97%止盈最长4天(45.1倍)
    #           'mid'=09:33挂(今开+昨收)/2限价/14:55兜底(12.9倍) | '0925'=次日竞价(8.3倍) | '1000'=次日10:00
    g.sell_mode = 'close'
    g.mz_mode = 'zero'            # 全自动口径: 买占恒0(实盘新日期无真值, 回测此口径=全自动真实保底) | 'hist'=内嵌真值(仅对账用)
    g.xq2_override = False   # C模式: 关覆盖层, 纯聚宽原生因子(真实收益预期)         # Q2极限对齐: 用Excel档位数据_Q2真值覆盖10因子(覆盖至2026-08-14)
    g.mz_extra = {}               # 实盘每日9:25前填问财主买占昨成，如 {'300828.XSHE': 1.35}
    g.d8_extra = []               # 实盘每天9:25前填问财"竞价抢筹"股，如 ['300828.XSHE']
    g.buy_time = '0925'           # '0925'=9:25竞价即买(默认, 688真值已内嵌同口径选股) | '0931'=等9:32科创分钟线通道(实盘新日期用)
    g.kc688 = True                # 实盘(内嵌数据覆盖不到的新日期)用9:32分钟线通道补688; False=关闭
    # 688买入方式(仅buy_time='0925'且9:27跑auction_trade时生效): 聚宽回测无沪市集合竞价价, 9:25市价买688必然废单(已实锤16笔全废)
    # 'fallback'=首选688时回退下一创业板候选(对齐原始最高收益版口径) | 'defer932'=688延迟到09:32分钟线市价买(688真实参与)
    g.buy688_mode = 'asis'

    # ---------- 状态 ----------
    g.static = None
    g.prev_auc = {}               # 昨日竞价 {code: (量股, 额元)}
    g.today_bought = []
    g.sold_today = []
    g.mid_orders = {}             # mid模式: {code: {'cost','target'}}
    g.force_sold = {}             # mid模式: 14:55市价成交参考价 {code: px}
    g.universe = []
    g.cand925 = None              # 09:25创业板候选(DataFrame, 未买入)
    g.d8_plain = set()            # 当日问财档8代码集(09:32复用)
    g.hold_days = {}              # holdzt/chand模式: {code: {'held':N,'maxh':X}}
    g.defer688 = None             # buy688_mode='defer932': 延迟到09:32买入的688代码

    # 09:25 创业板精确竞价选股(候选暂存不买入) → 09:32 科创板分钟线近似竞价选股+合并买入
    # (聚宽回测无688集合竞价数据, 实测列表/逐只均取不到; 9:31首根分钟bar的open=开盘价=竞价撮合价)
    run_daily(before_market_open, '09:00', reference_security='000300.XSHG')
    run_daily(auction_trade, '09:27', reference_security='000300.XSHG')
    run_daily(kc_minute_buy, '09:32', reference_security='000300.XSHG')
    run_daily(mid_limit_sell, '09:33', reference_security='000300.XSHG')
    run_daily(sell_at_10, '10:00', reference_security='000300.XSHG')
    run_daily(mid_force_sell, '14:55', reference_security='000300.XSHG')


def before_market_open(context):
    """09:00 盘前静态因子"""
    try:
        prev = context.previous_date
        current_data = get_current_data()
        all_stocks = get_all_securities(['stock'], prev)
        univ = [s for s in all_stocks.index
                if s.startswith(('300', '301', '302', '688', '689'))
                and not current_data[s].is_st
                and 'ST' not in current_data[s].name]
        if not univ:
            log.warning("盘前：双创股票池为空")
            g.static = None
            g.universe = []
            return

        q = query(valuation.code, valuation.turnover_ratio).filter(valuation.code.in_(univ))
        fdf = get_fundamentals(q, date=prev).set_index('code')

        hist = get_price(univ, end_date=prev, count=26, frequency='daily',
                         fields=['open', 'close', 'high', 'low', 'volume', 'money'],
                         skip_paused=False, fq=None, panel=False)

        rows = []
        for s, h in hist.groupby('code'):
            h = h.dropna(subset=['close'])
            if len(h) < 6:
                continue
            c = h['close'].values
            v = h['volume'].values
            prev_open, prev_close = h['open'].iloc[-1], c[-1]
            prev_high, prev_low = h['high'].iloc[-1], h['low'].iloc[-1]
            prev2_close = c[-2]
            ma5_prev = c[-5:].mean()
            pl_raw = (prev_close - ma5_prev) / ma5_prev * 100
            pl = np.sign(pl_raw) * np.floor(abs(pl_raw) * 100 + 0.5) / 100
            limit_yes = prev_close > prev2_close * 1.096
            yz = limit_yes and prev_high == prev_low == prev_close
            # 昨日竞价涨幅是否超物理极限（除权/数据异常相）→ 今日掩码
            kp_y = (prev_open / prev2_close - 1) * 100 if prev2_close > 0 else 0
            exr_y = (kp_y < -21.5) or (kp_y > 31.5)
            ls = 0
            for i in range(len(h) - 1, 0, -1):
                if v[i] > v[i - 1] and c[i] > c[i - 1]:
                    ls += 1
                else:
                    break
            llv20 = h['low'].iloc[-19:].min()   # 通达信LLV(L,20)含今日=过去19天+今日竞价价(9:25时L=O), 共20天
            zhs = float(fdf.loc[s, 'turnover_ratio']) if s in fdf.index else 0.0
            rows.append({'jcode': s, 'code': s.split('.')[0],
                         'prev_open': prev_open, 'prev_close': prev_close,
                         'pl': pl, 'yp': True, 'zhs': zhs, 'lv': prev_close < prev_open,
                         'limit_yes': limit_yes, 'yz': yz, 'ls': ls, 'llv20': llv20,
                         'exr_y': exr_y,
                         'amo_prev': float(h['money'].iloc[-1]),
                         'f46': float(F46.get(s, 0.0))})
        g.static = pd.DataFrame(rows).set_index('jcode') if rows else None
        g.universe = [r['jcode'] for r in rows if r['f46'] > 0]
        log.info("盘前静态因子完成：双创有效股票 %d 只" % len(g.universe))
    except Exception as e:
        log.error("before_market_open异常: %s" % e)
        g.static = None
        g.universe = []


def auction_trade(context):
    """09:27 竞价结果出来后: 卖旧仓(若0925模式) -> 竞价因子 -> 165组引擎 -> 首选半仓买入"""
    try:
        g.today_bought = []
        g.sold_today = []
        g.mid_orders = {}
        g.force_sold = {}
        g.cand925 = None            # 每日重置，防昨日候选残留
        g.df925 = None
        g.d8_plain = set()
        g.defer688 = None           # 每日重置688延迟买入标记
        current_data = get_current_data()

        # ---------- 0925模式: 先卖昨日持仓（竞价价成交） ----------
        if g.sell_mode == '0925':
            for s in list(context.portfolio.positions.keys()):
                pos = context.portfolio.positions[s]
                if pos.closeable_amount <= 0:
                    continue
                if current_data[s].paused:
                    log.warning("09:25 %s 停牌无法卖出，顺延" % s)
                    continue
                sell_px = current_data[s].last_price
                ret = (sell_px / pos.avg_cost - 1) * 100 if pos.avg_cost > 0 else 0
                log.info("🔴 09:25 竞价卖出 %s：%d股，成本%.3f 竞价参考%.3f 盈亏%.2f%%"
                         % (s, pos.closeable_amount, pos.avg_cost, sell_px, ret))
                g.sold_today.append({'code': s, 'cost': pos.avg_cost, 'sell_px': sell_px})
                order_target(s, 0, _mkt(s, False))

        if g.static is None or g.static.empty:
            log.warning("09:27 无静态因子表，今日空仓")
            return
        today = context.current_dt.date()
        univ = [s for s in g.universe if not current_data[s].paused]
        if not univ:
            log.warning("09:27 全部停牌，今日空仓")
            return

        # ---------- 集合竞价数据 ----------
        fields = ['time', 'current', 'volume', 'money',
                  'a1_v', 'a2_v', 'a3_v', 'a4_v', 'a5_v',
                  'b1_v', 'b2_v', 'b3_v', 'b4_v', 'b5_v']
        auc = None
        try:
            auc = get_call_auction(univ, start_date=today, end_date=today, fields=fields)
        except Exception as e1:
            log.warning("get_call_auction列表调用失败(%s)，改逐只获取" % e1)
            auc = None
        # --- 覆盖检测 + 逐只补缺：列表调用可能静默丢XSHG(科创板)，不能只在异常时才补缺 ---
        got = set(auc['code']) if (auc is not None and len(auc) > 0 and 'code' in auc.columns) else set()
        missing = [s for s in univ if s not in got]
        if missing:
            parts = [auc] if (auc is not None and len(auc) > 0 and 'code' in auc.columns) else []
            fixed = 0
            for s in missing:
                try:
                    d = get_call_auction(s, start_date=today, end_date=today, fields=fields)
                    if d is not None and len(d) > 0:
                        d = d.copy()
                        d['code'] = s
                        parts.append(d)
                        fixed += 1
                except Exception:
                    pass
            log.info("09:27 竞价补缺：列表缺%d只（沪%d/深%d），逐只补回%d只"
                     % (len(missing),
                        sum(1 for s in missing if s.endswith('XSHG')),
                        sum(1 for s in missing if s.endswith('XSHE')), fixed))
            auc = pd.concat(parts) if parts else None
        if auc is None or len(auc) == 0:
            log.error("09:27 未取到集合竞价数据，今日空仓")
            return
        auc_last = auc.groupby('code').last() if 'code' in auc.columns else auc.iloc[[-1]]
        n_hu = sum(1 for s in auc_last.index if str(s).endswith('XSHG'))
        n_sh0 = sum(1 for s in auc_last.index if str(s).endswith('XSHE'))
        log.info("09:27 竞价覆盖：深%d只/沪%d只（股票池%d只）" % (n_sh0, n_hu, len(univ)))

        # ---------- 竞价因子 ----------
        date_str = context.current_dt.strftime('%Y-%m-%d')
        d8_codes = set(D8.get(date_str, [])) | set(g.d8_extra)
        d8_plain = set(c.split('.')[0] for c in d8_codes)
        g.d8_plain = d8_plain
        mz_hist = MZ.get(context.current_dt.strftime('%Y%m%d'), {}) if g.mz_mode == 'hist' else {}

        new_auc = {}
        recs = []
        n_inj688 = 0
        auc688_today = AUC688.get(context.current_dt.strftime('%Y%m%d'), {})
        for s in univ:
            if s not in g.static.index:
                continue
            if s in auc_last.index:
                snap = auc_last.loc[s]
                ap = float(snap['current'])
                avol = float(snap['volume'])
                amoney = float(snap['money'])
            elif s.split('.')[0] in auc688_today:
                # 688竞价真值内嵌注入（回测环境聚宽无688竞价数据）
                _e = auc688_today[s.split('.')[0]]
                ap = float(_e[0])
                avol = float(_e[1])
                amoney = ap * avol   # 竞价单一价撮合, 额=价×量
                n_inj688 += 1
            else:
                continue
            if ap <= 0 or avol <= 0:
                continue
            new_auc[s] = (avol, amoney)
            st = g.static.loc[s]
            kp = (ap / st['prev_close'] - 1) * 100
            # 除权掩码: 今日超物理极限 或 昨日超物理极限 → 不选
            if (kp < -21.5) or (kp > 31.5) or st['exr_y']:
                continue
            jjl = avol / 100.0
            f46 = st['f46']
            jhs = jjl / f46 * 100000
            x3 = jjl / f46 * 10000 * kp
            base = (st['zhs'] > 20) and (-5 < kp < 0) and (jhs > 5)
            dix = jhs if base else np.nan
            fx = np.nan
            if base:
                rv = st['prev_close'] / min(st['llv20'], ap) * 100 - 100   # LLV含今日竞价价
                if rv < 80:
                    fx = rv
            qd = 500 - abs(x3 * 31) if base else np.nan
            snow = x3 * 31 if (kp < 9.6 and st['limit_yes'] and not st['yz']) else 0.0
            jz = amoney / st['amo_prev'] * 100 if st['amo_prev'] > 0 else np.nan
            # 主买占昨成: 手填(g.mz_extra) > 内嵌真值(MZ) > 0(保守口径)
            if s in g.mz_extra:
                mz = float(g.mz_extra[s])
            elif st['code'] in mz_hist:
                mz = float(mz_hist[st['code']])
            else:
                mz = 0.0
            if s in g.prev_auc and g.prev_auc[s][0] > 0:
                lb = jjl / (g.prev_auc[s][0] / 100.0)
                eb = amoney / g.prev_auc[s][1] if g.prev_auc[s][1] > 0 else np.nan
            else:
                lb, eb = 0.0, 0.0     # 通达信语义: 昨无记录=0 → 竞量比=0
            recs.append({'jcode': s, 'code': st['code'], 'kp': kp, 'pl': st['pl'],
                         'lb': lb, 'jz': jz, 'mz': mz, 'eb': eb, 'snow': snow,
                         'dix': dix, 'qd': qd, 'fx': fx, 'ke': st['zhs'],
                         'lv': st['lv'], 'ls': st['ls'], 'yp': st['yp'],
                         'auc_price': ap, 'auc_money': amoney})
        g.prev_auc = new_auc
        if auc688_today:
            log.info("09:27 内嵌688竞价真值注入 %d 只" % n_inj688)

        if not recs:
            log.info("09:27 无有效竞价数据，今日空仓")
            return
        df = pd.DataFrame(recs).set_index('jcode')
        if g.xq2_override:
            df = apply_xq2(df, XQ2.get(context.current_dt.strftime('%Y%m%d'), {}))

        # ---------- Q1 档位引擎 ----------
        df = q1_engine(df, d8_plain)
        g.df925 = df              # 供09:31科创通道判重
        cand = df[df['sx'] > 0].sort_values(['sx', 'code'], ascending=[False, True])

        # --- 688诊断：科创票在 进因子表/进候选 两个环节的存活数（正常应>0，为0说明竞价数据缺失） ---
        n688_rec = int(df['code'].str.startswith('688').sum())
        n688_cand = int(cand['code'].str.startswith('688').sum()) if not cand.empty else 0
        log.info("09:27 因子表%d只（含科创%d只）→ 候选%d只（含科创%d只）"
                 % (len(df), n688_rec, len(cand), n688_cand))

        log.info("=" * 80)
        log.info("✅ 09:27 战法三Q1信号 @ %s" % context.current_dt)
        if cand.empty:
            log.info("🟦 今日空仓（0候选）｜有档位%d只｜触雷%d只"
                     % (int((df['gear'] != 0).sum()), int((df['gear'] < 0).sum())))
            log.info("=" * 80)
            return

        log.info("📋 候选%d只（按首选序）:" % len(cand))
        for i, (jc, r) in enumerate(cand.head(10).iterrows(), 1):
            log.info("  %d. %s 档%.1f 首选序%.5f 开%.2f%% 量比%.2f 竞占%.2f 买占%.3f 额比%.2f "
                     "雪%.1f 乐%.2f 强%.0f 偏%.2f 险%.2f 客%.1f 连升%d 绿%d"
                     % (i, r['code'], r['gear'], r['sx'], r['kp'],
                        r['lb'], r['jz'], r['mz'] if pd.notna(r['mz']) else 0, r['eb'],
                        r['snow'], r['dix'] if pd.notna(r['dix']) else 0,
                        r['qd'] if pd.notna(r['qd']) else 0, r['pl'],
                        r['fx'] if pd.notna(r['fx']) else -1, r['ke'],
                        int(r['ls']), int(r['lv'])))

        # ---------- 候选暂存，09:31 与科创分钟线候选合并后统一买入 ----------
        g.cand925 = cand
        if g.buy_time == '0925':
            if not cand.empty:
                top = cand.iloc[0]
                log.info("🎯 首选：%s 档%.1f（竞价价 %.2f）" % (cand.index[0], top['gear'], top['auc_price']))
                _do_buy(context, cand, '创业0925')
            log.info("=" * 80)
            return
        if not cand.empty:
            top = cand.iloc[0]
            log.info("🎯 创业板首选：%s 档%.1f（竞价价 %.2f）——待09:32与科创候选合并后统一买入"
                     % (cand.index[0], top['gear'], top['auc_price']))
        _sell_desc = {'0925': '次日09:25竞价', '1000': '次日10:00',
                      'mid': '次日09:33挂估中位价限价单/14:55兜底市价',
                      'limit8': '次日09:33挂今开+8%限价单/14:55兜底市价',
                      'close': '次日14:55尾盘市价',
                      'holdzt': '涨停持有·断板次日14:55卖(最长4天)',
                      'chand': '吊灯97%止盈·最长4天'}[g.sell_mode]
        log.info("ℹ️ 纪律：%s 统一卖出" % _sell_desc)
        log.info("=" * 80)
    except Exception as e:
        log.error("auction_trade异常: %s" % e)


def _mkt(s, is_buy, ref_px=None):
    """市价单样式：科创板(688)按聚宽规则必须带保护限价，否则市价单直接废单
    注意: 9:27时聚宽688的last_price是昨收价(不是竞价价), 直接用它当保护限价会导致
          高开的688市价单静默不成交(开盘价>昨收保护价, 实测36/47笔没成交)!
    因此买入保护限价优先用当日竞价真值价auc_price(=开盘价, 必成交); 卖出用当前最新价"""
    if s.startswith('688'):
        cd = get_current_data()
        if is_buy and ref_px:
            lp = float(ref_px) * 1.002   # 竞价价+0.2%防舍入不成交, 成交价仍是开盘价
        else:
            lp = cd[s].last_price
        return MarketOrderStyle(round(float(lp), 2))
    return MarketOrderStyle()


def _do_buy(context, cand, src):
    """首选半仓市价买入（0925/0931两个时点共用）"""
    top = cand.iloc[0]
    target = cand.index[0]
    log.info("🎯 最终首选：%s 档%.1f（%s）" % (target, top['gear'], src))
    # 688在9:25/9:27竞价时点无法成交(聚宽回测无沪市集合竞价价, 实测市价单全废) → 按 buy688_mode 处理
    if target.startswith('688') and g.buy_time == '0925':
        if g.buy688_mode == 'fallback':
            alts = [c for c in cand.index if not c.startswith('688')]
            if not alts:
                log.warning("⚠️ 首选688且无创业板候选可回退，今日空仓")
                return
            target = alts[0]
            top = cand.loc[target]
            log.info("🔁 688首选回测竞价不可成交 → 回退创业板次选：%s 档%.1f（竞价价 %.2f）"
                     % (target, top['gear'], top['auc_price']))
        elif g.buy688_mode == 'defer932':
            g.defer688 = target
            log.info("⏰ 688首选 %s 延迟至09:32分钟线市价买入" % target)
            return
    if target in context.portfolio.positions:
        log.warning("⚠️ %s 已在持仓，今日不重复买入" % target)
        return
    buy_value = min(context.portfolio.total_value * g.position_ratio,
                    context.portfolio.available_cash)
    if buy_value < 1000:
        log.warning("可用资金不足，今日不买入")
        return
    _auc = float(top['auc_price']) if target.startswith('688') and 'auc_price' in cand.columns else None
    result = order_value(target, buy_value, _mkt(target, True, _auc))
    if result is not None:
        g.today_bought = [target]
        log.info("🟢 %s 已市价买入 %s，委托金额 %.2f 元"
                 % (context.current_dt.strftime('%H:%M'), target, buy_value))
    else:
        log.error("买入委托失败：%s" % target)


def kc_minute_buy(context):
    """09:32 科创板分钟线近似竞价通道 + 合并创业板候选统一买入
    原理: 聚宽回测无688集合竞价数据(实测列表/逐只均取不到, 研究环境有权限);
          9:31首根分钟bar的 open=当日开盘价=竞价撮合价(精确), volume/money≈竞价+首分钟(略偏大);
          昨日竞价量额用同口径近似值(g.prev_auc), lb/eb比值口径自洽"""
    try:
        if g.buy_time == '0925':
            # defer932模式: 9:27首选688延迟到这里用9:31分钟bar市价买入(此时688有真实行情, 可成交)
            if getattr(g, 'defer688', None):
                tgt = g.defer688
                g.defer688 = None
                if tgt in context.portfolio.positions:
                    log.warning("⚠️ %s 已在持仓，延迟买入取消" % tgt)
                    return
                bv = min(context.portfolio.total_value * g.position_ratio,
                         context.portfolio.available_cash)
                if bv < 1000:
                    log.warning("可用资金不足，688延迟买入取消")
                    return
                r = order_value(tgt, bv, _mkt(tgt, True))
                if r is not None:
                    g.today_bought = [tgt]
                    log.info("🟢 %s 688延迟市价买入 %s，委托金额 %.2f 元"
                             % (context.current_dt.strftime('%H:%M'), tgt, bv))
                else:
                    log.error("688延迟买入委托失败：%s" % tgt)
            return   # 9:25已用内嵌真值完成688选股买入, 分钟线通道仅0931模式启用
        current_data = get_current_data()
        recs = []
        if g.kc688 and g.static is not None and not g.static.empty:
            univ688 = [s for s in g.universe
                       if s.startswith('688') and not current_data[s].paused]
            # 9:25已拿到精确竞价数据的(研究/实盘环境)不重复算
            got925 = set(g.cand925.index) if g.cand925 is not None else set()
            if g.df925 is not None:
                got925 |= set(g.df925.index)
            univ688 = [s for s in univ688 if s not in got925]
            if univ688:
                try:
                    m1 = get_price(univ688, end_date=context.current_dt, count=5,
                                   frequency='1m', fields=['open', 'volume', 'money'],
                                   skip_paused=False, fq=None, panel=False)
                except Exception as e1:
                    log.warning("09:32 科创分钟线获取失败(%s)" % e1)
                    m1 = None
                if m1 is not None and len(m1) > 0 and 'code' in m1.columns:
                    today_s = context.current_dt.strftime('%Y-%m-%d')
                    if 'time' in m1.columns:
                        # 只保留今日bar，防取到昨日尾盘bar（时间边界坑）
                        m1 = m1[m1['time'].astype(str).str[:10] == today_s]
                    m1 = m1.dropna(subset=['open'])
                    # 每只取今日第一根分钟bar（含集合竞价成交量），与bar时间标注口径无关
                    m1 = m1.groupby('code').first().reset_index()
                    log.info("09:32 科创分钟线：池%d只 → 今日bar%d只" % (len(univ688), len(m1)))
                    date_str = context.current_dt.strftime('%Y-%m-%d')
                    mz_hist = MZ.get(context.current_dt.strftime('%Y%m%d'), {}) if g.mz_mode == 'hist' else {}
                    for _, r1 in m1.iterrows():
                        s = r1['code']
                        if s not in g.static.index:
                            continue
                        # 竞价价用官方 day_open 字段（=开盘价=竞价撮合价，精确，不用bar的open防口径差异）
                        ap = float(current_data[s].day_open or 0)
                        if ap <= 0:
                            ap = float(r1['open'])
                        avol = float(r1['volume'])
                        amoney = float(r1['money'])
                        if ap <= 0 or avol <= 0:
                            continue
                        st = g.static.loc[s]
                        kp = (ap / st['prev_close'] - 1) * 100
                        if (kp < -21.5) or (kp > 31.5) or st['exr_y']:
                            continue
                        jjl = avol / 100.0
                        f46 = st['f46']
                        jhs = jjl / f46 * 100000
                        x3 = jjl / f46 * 10000 * kp
                        base = (st['zhs'] > 20) and (-5 < kp < 0) and (jhs > 5)
                        dix = jhs if base else np.nan
                        fx = np.nan
                        if base:
                            rv = st['prev_close'] / min(st['llv20'], ap) * 100 - 100
                            if rv < 80:
                                fx = rv
                        qd = 500 - abs(x3 * 31) if base else np.nan
                        snow = x3 * 31 if (kp < 9.6 and st['limit_yes'] and not st['yz']) else 0.0
                        jz = amoney / st['amo_prev'] * 100 if st['amo_prev'] > 0 else np.nan
                        if s in g.mz_extra:
                            mz = float(g.mz_extra[s])
                        elif st['code'] in mz_hist:
                            mz = float(mz_hist[st['code']])
                        else:
                            mz = 0.0
                        if s in g.prev_auc and g.prev_auc[s][0] > 0:
                            lb = jjl / (g.prev_auc[s][0] / 100.0)
                            eb = amoney / g.prev_auc[s][1] if g.prev_auc[s][1] > 0 else np.nan
                        else:
                            lb, eb = 0.0, 0.0
                        recs.append({'jcode': s, 'code': st['code'], 'kp': kp, 'pl': st['pl'],
                                     'lb': lb, 'jz': jz, 'mz': mz, 'eb': eb, 'snow': snow,
                                     'dix': dix, 'qd': qd, 'fx': fx, 'ke': st['zhs'],
                                     'lv': st['lv'], 'ls': st['ls'], 'yp': st['yp'],
                                     'auc_price': ap, 'auc_money': amoney})
                        g.prev_auc[s] = (avol, amoney)   # 同口径存昨日近似竞价
        cand688 = pd.DataFrame()
        if recs:
            df688 = pd.DataFrame(recs).set_index('jcode')
            if g.xq2_override:
                df688 = apply_xq2(df688, XQ2.get(context.current_dt.strftime('%Y%m%d'), {}))
            df688 = q1_engine(df688, g.d8_plain)
            cand688 = df688[df688['sx'] > 0].sort_values(['sx', 'code'], ascending=[False, True])
            log.info("09:32 科创分钟线：因子表%d只 → 候选%d只" % (len(df688), len(cand688)))
        else:
            log.info("09:32 科创分钟线：无有效数据")

        # ---------- 合并候选，首选半仓买入 ----------
        parts = [c for c in (g.cand925, cand688) if c is not None and len(c) > 0]
        if not parts:
            log.info("🟦 09:31 合并后仍无候选，今日空仓")
            return
        cand = pd.concat(parts).sort_values(['sx', 'code'], ascending=[False, True])
        if g.today_bought:
            log.info("09:32 今日已买入（0925模式），科创通道仅记录不再买")
            return
        src = '科创' if cand.index[0].startswith('688') else '创业'
        _do_buy(context, cand, src + '0931')
    except Exception as e:
        log.error("kc_minute_buy异常: %s" % e)


def mid_limit_sell(context):
    """09:33 限价挂单模式: 'mid'挂(今开+昨收)/2 | 'limit8'挂今开×1.08 —— 冲高触及即成交; 未成交14:55兜底"""
    try:
        if g.sell_mode not in ('mid', 'limit8'):
            return
        current_data = get_current_data()
        for s in list(context.portfolio.positions.keys()):
            pos = context.portfolio.positions[s]
            if pos.closeable_amount <= 0 or s in g.today_bought:
                continue
            if current_data[s].paused:
                log.warning("09:33 %s 停牌无法卖出，顺延" % s)
                continue
            day_open = current_data[s].day_open
            if day_open is None or day_open <= 0:
                continue
            if g.sell_mode == 'limit8':
                target_px = round(day_open * 1.08, 2)
            else:
                prev_close = None
                if g.static is not None and s in g.static.index:
                    prev_close = float(g.static.loc[s, 'prev_close'])
                if prev_close is None or prev_close <= 0:
                    prev_close = pos.avg_cost   # 兜底
                target_px = round((day_open + prev_close) / 2, 2)
            order_target(s, 0, LimitOrderStyle(target_px))
            g.mid_orders[s] = {'cost': pos.avg_cost, 'target': target_px}
            log.info("📌 09:33 %s 挂限价卖单 %.2f（模式%s，今开%.2f，成本%.3f，未成交14:55市价兜底）"
                     % (s, target_px, g.sell_mode, day_open, pos.avg_cost))
    except Exception as e:
        log.error("mid_limit_sell异常: %s" % e)


def mid_force_sell(context):
    """14:55 尾盘卖出:
    'close'=直接市价清; 'mid'/'limit8'=撤未成交限价单再市价清;
    'holdzt'=涨停则持有(断板卖, 最多4天); 'chand'=收盘跌破持仓期最高价97%才卖(最多4天)"""
    try:
        if g.sell_mode not in ('mid', 'limit8', 'close', 'holdzt', 'chand'):
            return
        for o in get_open_orders():
            try:
                cancel_order(o)
            except Exception:
                pass
        current_data = get_current_data()
        for s in list(context.portfolio.positions.keys()):
            pos = context.portfolio.positions[s]
            if pos.closeable_amount <= 0 or s in g.today_bought:
                continue
            if current_data[s].paused:
                log.warning("14:55 %s 停牌无法卖出，顺延" % s)
                continue
            sell_px = current_data[s].last_price
            # ---------- 持有型卖出模式判定 ----------
            if g.sell_mode in ('holdzt', 'chand'):
                info = g.hold_days.get(s, {'held': 0, 'maxh': 0.0})
                info['held'] += 1
                prev_close = float(g.static.loc[s, 'prev_close'])                     if (g.static is not None and s in g.static.index) else pos.avg_cost
                if g.sell_mode == 'holdzt':
                    if sell_px >= prev_close * 1.197 and info['held'] < 4:
                        g.hold_days[s] = info
                        log.info("📌 14:55 %s 涨停继续持有（第%d天，现价%.2f）" % (s, info['held'], sell_px))
                        continue
                else:  # chand: 今日最高价(分钟线聚合)纳入吊灯锚点
                    try:
                        hh = get_price(s, end_date=context.current_dt, count=240,
                                       frequency='1m', fields=['high'],
                                       skip_paused=False, fq=None, panel=False)
                        day_high = float(hh['high'].max())
                    except Exception:
                        day_high = sell_px
                    info['maxh'] = max(info['maxh'], day_high)
                    if sell_px > info['maxh'] * 0.97 and info['held'] < 4:
                        g.hold_days[s] = info
                        log.info("📌 14:55 %s 吊灯继续持有（第%d天，现价%.2f 锚高%.2f）"
                                 % (s, info['held'], sell_px, info['maxh']))
                        continue
                g.hold_days.pop(s, None)
            ret = (sell_px / pos.avg_cost - 1) * 100 if pos.avg_cost > 0 else 0
            _why = '尾盘市价卖出' if g.sell_mode == 'close' else '限价未成交，市价卖出'
            log.info("🔴 14:55 %s %s：%d股，盈亏%.2f%%"
                     % (_why, s, pos.closeable_amount, ret))
            g.force_sold[s] = sell_px
            order_target(s, 0, _mkt(s, False))
    except Exception as e:
        log.error("mid_force_sell异常: %s" % e)


def sell_at_10(context):
    """10:00 统一卖出（仅 sell_mode='1000' 时生效）"""
    try:
        if g.sell_mode != '1000':
            return
        positions = context.portfolio.positions
        if len(positions) == 0:
            return
        current_data = get_current_data()
        for s in list(positions.keys()):
            pos = positions[s]
            if pos.closeable_amount <= 0 or s in g.today_bought:
                continue
            if current_data[s].paused:
                log.warning("10:00 %s 停牌无法卖出，顺延" % s)
                continue
            sell_px = current_data[s].last_price
            ret = (sell_px / pos.avg_cost - 1) * 100 if pos.avg_cost > 0 else 0
            log.info("🔴 10:00 卖出 %s：%d股，成本%.3f 现价%.3f 盈亏%.2f%%"
                     % (s, pos.closeable_amount, pos.avg_cost, sell_px, ret))
            g.sold_today.append({'code': s, 'cost': pos.avg_cost, 'sell_px': sell_px})
            order_target(s, 0, _mkt(s, False))
    except Exception as e:
        log.error("sell_at_10异常: %s" % e)


def after_trading_end(context):
    """收盘对账：理论中位价收益(Excel口径) vs 实际卖出口径"""
    try:
        today = context.current_dt.date()
        entries = []
        if g.sell_mode == 'mid':
            # mid模式: 从挂单记录重建成交结果
            for s, info in g.mid_orders.items():
                if s in g.force_sold:
                    entries.append({'code': s, 'cost': info['cost'], 'sell_px': g.force_sold[s]})
                elif s not in context.portfolio.positions or                         context.portfolio.positions[s].total_amount == 0:
                    entries.append({'code': s, 'cost': info['cost'], 'sell_px': info['target']})
        else:
            entries = g.sold_today
        if not entries:
            return
        log.info("-" * 80)
        log.info("📒 收盘对账（Excel中位价口径 vs 本策略%s口径）:" % g.sell_mode)
        for r in entries:
            try:
                h = get_price(r['code'], end_date=today, count=1, frequency='daily',
                              fields=['low', 'high'], skip_paused=False, fq=None, panel=False)
                mid = (float(h['low'].iloc[-1]) + float(h['high'].iloc[-1])) / 2
                theory = (mid / r['cost'] - 1) * 100
                actual = (r['sell_px'] / r['cost'] - 1) * 100
                log.info("  %s 成本%.3f｜理论中位价%.3f(%+.2f%%)｜实卖%.3f(%+.2f%%)"
                         % (r['code'], r['cost'], mid, theory, r['sell_px'], actual))
            except Exception:
                pass
        log.info("-" * 80)
    except Exception as e:
        log.error("after_trading_end异常: %s" % e)


def apply_xq2(df, ov):
    """Q2极限对齐: 用Excel档位数据_Q2真值覆盖10个因子 [量比,额比,乐,雪,偏,险,强,客,连升,绿]"""
    if not ov:
        return df
    m = df['code'].isin(ov)
    if not m.any():
        return df
    cols = ['lb', 'eb', 'dix', 'snow', 'pl', 'fx', 'qd', 'ke', 'ls', 'lv']
    codes = df.loc[m, 'code']
    for i, c in enumerate(cols):
        df.loc[m, c] = codes.map(lambda c2, i=i: ov[c2][i])
    df.loc[m, 'yp'] = df.loc[m, 'pl'].notna()
    return df


def q1_engine(df, d8_plain):
    """Q1 v4 公式IF链档位/首选序（与Excel回测引擎逐行同源）"""
    df = df.copy()
    df['huan'] = df['dix'].notna() & (df['dix'] > 0)
    df['yu'] = df['ls'] >= 3
    env = {c: df[c] for c in ['pl', 'kp', 'lb', 'jz', 'mz', 'eb', 'snow',
                              'dix', 'qd', 'fx', 'huan', 'yp', 'ke', 'lv', 'yu', 'ls']}
    env['code'] = df['code']
    def ev(s):
        return eval(s, {'__builtins__': {}}, env).fillna(False).astype(bool)
    cy = df['code'].str.startswith(('300', '301'))
    sc = df['code'].str.startswith(('300', '301', '688', '689'))
    qc = (df['jz'] > 20) & (df['mz'] > 0.6) & df['yp'] & (df['pl'] < 18)
    dm = (df['mz'] > 1.2) & (df['jz'] > 5) & df['yp'] & (df['pl'] < 18)
    pool = sc & (df['lb'] > 0) & (df['huan'] | (df['snow'] > 0) | qc | dm)
    leiC = (df['kp'] >= 9.6) | ((df['snow'] > 80) & (df['kp'] >= 7) & (df['kp'] < 9.6))
    leiE = (df['snow'] > 200) & cy
    leiK = df['yp'] & (df['pl'] >= 12) & (df['pl'] < 15) & (df['eb'] > 3)
    leiL = df['lb'] > 200
    leiM = df['mz'] > 6.5
    lei = leiC | leiE | leiK | leiL | leiM
    hit = {}
    for gg in (6, 5, 4, 3):
        h = pd.Series(False, index=df.index)
        for e in TIER[gg]:
            h |= ev(e)
        hit[gg] = h & pool & ~lei
    b29 = sc & df['huan'] & (df['lb'] >= 1.5) & (df['lb'] < 3.7) & df['fx'].notna() & (df['fx'] < 20) & ~lei
    g9 = (qc & (df['mz'] >= 1) & (df['mz'] < 3)) | (dm & (df['pl'] >= -3) & (df['pl'] < 0))
    pl25 = (df['kp'] >= 2) & (df['kp'] < 5)
    gear = pd.Series(0.0, index=df.index)
    gear = gear.mask(pool & leiC, -0.1).mask(pool & ~leiC & leiE, -0.2).mask(pool & ~leiC & ~leiE & leiK, -0.3)
    gear = gear.mask(pool & ~leiC & ~leiE & ~leiK & leiL, -0.4).mask(pool & ~leiC & ~leiE & ~leiK & ~leiL & leiM, -0.5)
    for gg in (6, 5, 4, 3):
        gear = gear.mask((gear == 0) & hit[gg], float(gg))
    gear = gear.mask((gear == 0) & b29, 2.9)
    gear = gear.mask((gear == 0) & (df['snow'] > 0), 1.8)
    gear = gear.mask((gear == 0) & ~pl25 & g9, 2.8)
    gear = gear.mask((gear == 0) & ~pl25 & qc, 2.7)
    gear = gear.mask((gear == 0) & ~pl25 & dm, 2.6)
    key6 = (df['jz'] * df['mz']).clip(upper=9999)
    key5 = (100 - df['kp']).clip(lower=0).clip(upper=9999)
    keyd = df['dix'].fillna(0).clip(upper=9999)
    sx = pd.Series(0.0, index=df.index)
    sx = sx.mask(gear == 6, 6 + np.where(df['yu'], 0.04, 0) + key6 * 0.0000035)
    sx = sx.mask(gear.isin([5, 4, 3]), gear + np.where(df['yu'], 0.04, 0) + key5 * 0.0000035)
    sx = sx.mask(gear == 2.9, 2.9 + np.where(df['yu'], 0.04, 0) + keyd * 0.0000035)
    df['gear'] = gear
    df['sx'] = sx
    return df
